var t=`0775-agatogo`;var n=`world-0775`;var a=`RW`;var s=`eastern-africa`;var o=4;var r=582;var l={en:`Agatogo`,ua:`Агатого`};var d={en:`Agatogo is a Rwanda classic prepared with black-eyed peas, yellow onion, garlic, plantain. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Агатого, страва кухні країни Руанда зі складниками: квасоля чорноочка, жовта цибуля, часник, плантан. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Soak the dried beans or peas in plentiful cold water for 480 minutes, then drain and discard the soaking liquid; keep refrigerated in hot conditions.`,ua:`Замочіть сухі бобові у великій кількості холодної води на 480 хвилин, після чого злийте й вилийте воду від замочування; за спеки тримайте в холодильнику.`,t:[`soaking-legumes`],m:480,i:[[`black-eyed-peas`,280,`g`],[`water`,700,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 55 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 55 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:55,i:[[`water`,900,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,160,`g`],[`red-palm-oil`,38,`ml`],[`garlic`,3,`clove`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 33 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 33 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:33,i:[[`plantain`,500,`g`],[`tomato`,290,`g`],[`water`,550,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,18,`g`],[`table-salt`,null,`to_taste`]]}];var m={slug:t,id:n,country:`RW`,region:s,servings:4,minutes:582,title:l,text:d,steps:g};export{a as country,m as default,n as id,r as minutes,s as region,o as servings,t as slug,g as steps,d as text,l as title};